@@ -202,1 +202,1 @@
+  public void testContainsWithFlattenedPolygon() throws Exception {
+    Polygon polygon =
+        new Polygon(
+            new double[] {0, 0, 10, 10, 10 - 1e-9, 10 - 1e-9, 10, 10, 0},
+            new double[] {0, 10, 10, 9, 9, 1, 1, 0, 0});
+    try (Directory dir = newDirectory();
+        RandomIndexWriter writer = new RandomIndexWriter(random(), dir)) {
+      Document document = new Document();
+      addPolygonsToDoc(FIELDNAME, document, polygon);
+      writer.addDocument(document);
+      try (IndexReader reader = writer.getReader()) {
+        IndexSearcher searcher = newSearcher(reader);
+        LatLonGeometry[] queries = {
+          new Polygon(
+              new double[] {9, 9, 11, 11, 9},
+              new double[] {0.25, 0.75, 0.75, 0.25, 0.25}),
+          new Rectangle(9, 11, 0.25, 0.75),
+          new Line(new double[] {9, 11}, new double[] {0.5, 0.5})
+        };
+        for (LatLonGeometry query : queries) {
+          assertEquals(
+              0,
+              searcher.count(LatLonShape.newGeometryQuery(FIELDNAME, QueryRelation.CONTAINS, query)));
+          assertEquals(
+              1,
+              searcher.count(
+                  LatLonShape.newGeometryQuery(FIELDNAME, QueryRelation.INTERSECTS, query)));
+          assertEquals(
+              0, searcher.count(LatLonShape.newGeometryQuery(FIELDNAME, QueryRelation.WITHIN, query)));
+          assertEquals(
+              0,
+              searcher.count(LatLonShape.newGeometryQuery(FIELDNAME, QueryRelation.DISJOINT, query)));
+        }
+        assertEquals(
+            0,
+            searcher.count(
+                LatLonShape.newBoxQuery(FIELDNAME, QueryRelation.CONTAINS, 9, 11, 0.25, 0.75)));
+        assertEquals(
+            1,
+            searcher.count(
+                LatLonShape.newBoxQuery(FIELDNAME, QueryRelation.CONTAINS, 8, 9, 0.25, 0.75)));
+      }
+    }
+  }
+
   /** test random polygons with a single hole */
PATCH
